mapper.select:
SELECT a.name_ AS "name", a.assignee_ AS "assignee", AVG(a.duration_ ) as "avgTime", MAX(a.duration_ ) as "maxTime", COUNT(a.task_def_key_) as "countNum", b.name_ AS "procDefName" FROM act_hi_taskinst a LEFT JOIN act_re_procdef b ON a.proc_def_id_ =b.ID_
a.duration_ is not null
AND a.name_ LIKE #{likeName}
AND b.name_ LIKE #{likeProcDefName}
GROUP BY a.task_def_key_, b.name_, a.assignee_,a.name_
ORDER BY ${orderBy}
ORDER BY a.task_def_key_ desc,a.name_ desc
